const App = () => {
  const [count, setCount] = useState(0);

  return (
    <div>
      <h1>{count}</h1>
      <button onClick={() => setCount(c => c + 1)}>Increment</button>
      <Button 
        onClick={() => console.log('Click')} 
        config={{ style: { color: 'red' } }}
      >
        Submit
      </Button>
    </div>
  );
};

const Component = ({ a, b }) => {
  // a and b are numbers
  const sum = useMemo(() => a + b, [a, b]);
  return <div>{sum}</div>;
};
